export class FaceTracker{
 constructor(){this.worker=null;this.pending=null;this.id=0;this.lastTime=-1;this.lastResult={faceLandmarks:[],faceBlendshapes:[]};this.seen=0;this.disposed=false;this.status='Off';this.mode='VIDEO';}
 async init(){if(this.ready)return this.ready;this.status='Loading local face model…';this.ready=this.initialize();return this.ready;}
 async initialize(){try{await new Promise((resolve,reject)=>{const w=this.worker=new Worker(new URL('./face-tracker-worker.js',import.meta.url));w.onmessage=({data:d})=>{if(d.type==='ready')resolve();else if(d.type==='result'){this.lastResult=d.result;this.seen=performance.now();const p=this.pending;this.pending=null;p?.resolve(d.result);}else if(d.type==='error'){const p=this.pending;this.pending=null;p?.reject(Error(d.message));reject(Error(d.message));}};w.onerror=e=>reject(Error(e.message||'Worker could not start'));w.postMessage({type:'init'});});this.status='Local face tracking ready';}catch(workerError){this.worker?.terminate();this.worker=null;if(this.disposed)return;const {FilesetResolver,FaceLandmarker}=await import('../vendor/vision/vision_bundle.mjs');const canvas=document.createElement('canvas');if(!canvas.getContext('webgl2'))throw Error('Face tracking needs WebGL 2. Enable browser graphics acceleration or use another browser; photo editing and custom monsters still work.');this.model=await FaceLandmarker.createFromOptions(await FilesetResolver.forVisionTasks(new URL('../vendor/vision',import.meta.url).href),{canvas,baseOptions:{modelAssetPath:new URL('../vendor/vision/face_landmarker.task',import.meta.url).href,delegate:'GPU'},runningMode:'VIDEO',numFaces:2,outputFaceBlendshapes:true,minFaceDetectionConfidence:.5,minFacePresenceConfidence:.5,minTrackingConfidence:.5});if(this.disposed){this.model.close();this.model=null;return;}this.status='Local face tracking ready · compatibility mode';}}
 async detect(source,image=false){await this.init();if(this.disposed||this.pending)return this.lastResult;const mode=image?'IMAGE':'VIDEO',time=Math.max(performance.now(),this.lastTime+1);this.lastTime=time;if(this.model){if(this.mode!==mode){await this.model.setOptions({runningMode:mode});this.mode=mode;}this.lastResult=image?this.model.detect(source):this.model.detectForVideo(source,time);this.seen=performance.now();return this.lastResult;}const bitmap=await createImageBitmap(source);if(this.disposed){bitmap.close();return this.lastResult;}const id=++this.id;return new Promise((resolve,reject)=>{this.pending={resolve,reject,id};this.worker.postMessage({type:'detect',id,time,mode,image:bitmap},[bitmap]);});}
 faces(now=performance.now()){return now-this.seen<500?this.lastResult:{faceLandmarks:[],faceBlendshapes:[]};}
 dispose(){this.disposed=true;this.pending?.resolve({faceLandmarks:[],faceBlendshapes:[]});this.pending=null;this.worker?.terminate();this.worker=null;this.model?.close();this.model=null;}
}
